export function completionCard(count) {
  return `<div class="quiz-content center result-page completion-card"><svg class="completion-star" viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="57" fill="#fff3ce"/><path d="m60 19 12 25 28 4-20 20 5 28-25-13-25 13 5-28-20-20 28-4Z" fill="#f1c453" stroke="#997024" stroke-width="3" stroke-linejoin="round"/><path d="m46 59 10 10 20-23" fill="none" stroke="#6d501d" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg><h1>你完成了，真棒！</h1><p>獲得 <strong>${count}</strong> 顆安心星</p><div class="answer-actions"><button class="primary" data-finish="rewards">看獎勵 <span aria-hidden="true">→</span></button></div></div>`;
}
